import{_ as a}from"./chunks/figure-1.7NSxEyVz.js";import{_ as t}from"./chunks/figure-2.BkNzXdts.js";import{_ as n}from"./chunks/infinite_timeev.BELJXst5.js";import{_ as i}from"./chunks/figure-3.D3vOFNRR.js";import{_ as d}from"./chunks/figure-2.BG5GI4Uo.js";import{_ as o}from"./chunks/figure-3.DvvOLLjv.js";import{_ as r}from"./chunks/figure-2.PcR_EGNs.js";import{_ as s}from"./chunks/figure-1.DAQIbkR-.js";import{_ as m}from"./chunks/figure-6.QA8YqFjU.js";import{_ as l}from"./chunks/figure-1.CO_8w6ES.js";import{_ as c,o as h,c as u,ao as p}from"./chunks/framework.CvmVtbJQ.js";const F=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md","lastUpdated":null}'),g={name:"examples/index.md"};function f(b,e,x,y,q,_){return h(),u("div",null,[...e[0]||(e[0]=[p('<h1 id="Examples" tabindex="-1">Examples <a class="header-anchor" href="#Examples" aria-label="Permalink to &quot;Examples {#Examples}&quot;">​</a></h1><p>This gallery collects the full worked examples that ship with MPSKit.jl. Each one is a complete, runnable script (also available as a Jupyter notebook, linked from the example page itself) that goes well beyond the short snippets in the how-to guides.</p><p>Within each physics grouping below, the examples are listed roughly in order of increasing difficulty: start at the top if you are new to MPSKit, and work down as you get comfortable with symmetries, infinite systems, and the less common algorithms.</p><h2 id="Quantum-11d" tabindex="-1">Quantum (1+1)d <a class="header-anchor" href="#Quantum-11d" aria-label="Permalink to &quot;Quantum (1+1)d {#Quantum-11d}&quot;">​</a></h2><h3 id="The-transverse-field-Ising-model:-a-complete-ground-state-studyquantum1d/0.tfim-groundstate/index.md" tabindex="-1"><a href="./quantum1d/0.tfim-groundstate/">The transverse-field Ising model: a complete ground-state study</a> <a class="header-anchor" href="#The-transverse-field-Ising-model:-a-complete-ground-state-studyquantum1d/0.tfim-groundstate/index.md" aria-label="Permalink to &quot;[The transverse-field Ising model: a complete ground-state study](quantum1d/0.tfim-groundstate/index.md) {#The-transverse-field-Ising-model:-a-complete-ground-state-studyquantum1d/0.tfim-groundstate/index.md}&quot;">​</a></h3><p><img src="'+a+'" alt=""></p><p>Assembles the tools from the tutorials into one case study of the TFIM phase transition: finite-ring <code>DMRG</code> versus infinite-chain <code>VUMPS</code> magnetization curves in a single figure, plus the entanglement entropy and correlation length of the infinite state across the transition. The natural first example after finishing the tutorial track. <strong>Level: introductory.</strong></p><h3 id="The-Ising-CFT-spectrumquantum1d/1.ising-cft/index.md" tabindex="-1"><a href="./quantum1d/1.ising-cft/">The Ising CFT spectrum</a> <a class="header-anchor" href="#The-Ising-CFT-spectrumquantum1d/1.ising-cft/index.md" aria-label="Permalink to &quot;[The Ising CFT spectrum](quantum1d/1.ising-cft/index.md) {#The-Ising-CFT-spectrumquantum1d/1.ising-cft/index.md}&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>Extracts the finite-size conformal spectrum of the critical transverse-field Ising chain, first by brute-force <code>exact_diagonalization</code> on a small periodic chain, then by extending to larger sizes with finite <code>DMRG</code> and the <code>QuasiparticleAnsatz</code>, using a translation MPO to assign a momentum label to each state. No symmetries are used, which makes this a good entry point into the finite-MPS workflow. <strong>Level: introductory.</strong></p><h3 id="DQPT-in-the-Ising-modelquantum1d/3.ising-dqpt/index.md" tabindex="-1"><a href="./quantum1d/3.ising-dqpt/">DQPT in the Ising model</a> <a class="header-anchor" href="#DQPT-in-the-Ising-modelquantum1d/3.ising-dqpt/index.md" aria-label="Permalink to &quot;[DQPT in the Ising model](quantum1d/3.ising-dqpt/index.md) {#DQPT-in-the-Ising-modelquantum1d/3.ising-dqpt/index.md}&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><p>Quenches the transverse-field Ising chain across its critical point and tracks the Loschmidt echo in search of non-analyticities (dynamical quantum phase transitions), on both a finite chain (<code>TDVP2</code>/<code>TDVP</code>) and directly in the thermodynamic limit (<code>changebonds</code> with <code>OptimalExpand</code>, then <code>TDVP</code>). A compact introduction to real-time evolution and environment reuse, still without symmetries. <strong>Level: introductory/intermediate.</strong></p><h3 id="The-Haldane-gapquantum1d/2.haldane/index.md" tabindex="-1"><a href="./quantum1d/2.haldane/">The Haldane gap</a> <a class="header-anchor" href="#The-Haldane-gapquantum1d/2.haldane/index.md" aria-label="Permalink to &quot;[The Haldane gap](quantum1d/2.haldane/index.md) {#The-Haldane-gapquantum1d/2.haldane/index.md}&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>Computes the Haldane gap of the spin-1 Heisenberg antiferromagnet in two complementary ways: finite-size <code>DMRG</code> with the <code>QuasiparticleAnsatz</code>, extrapolated over system size, and a direct infinite-chain <code>VUMPS</code> calculation with a momentum-resolved excitation scan. Introduces <code>SU2Irrep</code>/<code>SU2Space</code> symmetric tensors for both <code>FiniteMPS</code> and <code>InfiniteMPS</code>. <strong>Level: intermediate.</strong></p><h3 id="The-XXZ-modelquantum1d/4.xxz-heisenberg/index.md" tabindex="-1"><a href="./quantum1d/4.xxz-heisenberg/">The XXZ model</a> <a class="header-anchor" href="#The-XXZ-modelquantum1d/4.xxz-heisenberg/index.md" aria-label="Permalink to &quot;[The XXZ model](quantum1d/4.xxz-heisenberg/index.md) {#The-XXZ-modelquantum1d/4.xxz-heisenberg/index.md}&quot;">​</a></h3><p><img src="'+d+'" alt=""></p><p>Walks through a ground-state search that first goes wrong: single-site <code>VUMPS</code> and <code>GradientGrassmann</code> stall on the spin-1/2 Heisenberg antiferromagnet, and <code>transferplot</code>/<code>entanglementplot</code> reveal a near-non-injective state with several almost-degenerate transfer-matrix eigenvalues. The fix is a two-site unit cell together with the <code>SU2Irrep</code>-symmetric Hamiltonian, after which <code>IDMRG2</code> and <code>VUMPS</code> converge cleanly. A useful, diagnostic-driven example for recognizing and debugging convergence failures. <strong>Level: intermediate.</strong></p><h3 id="Spin-1-Heisenberg-modelquantum1d/5.haldane-spt/index.md" tabindex="-1"><a href="./quantum1d/5.haldane-spt/">Spin 1 Heisenberg model</a> <a class="header-anchor" href="#Spin-1-Heisenberg-modelquantum1d/5.haldane-spt/index.md" aria-label="Permalink to &quot;[Spin 1 Heisenberg model](quantum1d/5.haldane-spt/index.md) {#Spin-1-Heisenberg-modelquantum1d/5.haldane-spt/index.md}&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>Distinguishes the two symmetry-protected topological phases of the SU(2)-symmetric spin-1 Heisenberg chain by restricting the virtual <code>SU2Space</code> to integer or half-integer charges, then compares the two resulting ground states through their energy, transfer-matrix spectrum (<code>transferplot</code>), entanglement spectrum (<code>entanglementplot</code>), and entanglement entropy (<code>entropy</code>). Builds directly on the symmetry machinery introduced in the Haldane gap example. <strong>Level: intermediate/advanced.</strong></p><h3 id="Hubbard-chain-at-half-fillingquantum1d/6.hubbard/index.md" tabindex="-1"><a href="./quantum1d/6.hubbard/">Hubbard chain at half filling</a> <a class="header-anchor" href="#Hubbard-chain-at-half-fillingquantum1d/6.hubbard/index.md" aria-label="Permalink to &quot;[Hubbard chain at half filling](quantum1d/6.hubbard/index.md) {#Hubbard-chain-at-half-fillingquantum1d/6.hubbard/index.md}&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>Studies the 1D Hubbard model at half filling with fermionic <code>InfiniteMPS</code>, first benchmarking a plain <code>VUMPS</code>/<code>GradientGrassmann</code> ground-state search against the exact Bethe-ansatz integral for the energy, then imposing the full particle-number and spin symmetry (<code>U1Irrep</code>, <code>SU2Irrep</code>, with <code>MPSKit.add_physical_charge</code> to pin the filling) and constructing the spinon/holon excitation spectrum with the <code>QuasiparticleAnsatz</code>. Combines fermionic symmetry sectors with a more elaborate ground-state recipe (staged bond-dimension growth via <code>changebonds</code>/<code>OptimalExpand</code>, <code>SvdCut</code>, and mixed <code>VUMPS</code>/<code>GradientGrassmann</code> refinement). <strong>Level: advanced.</strong></p><h3 id="Finite-temperature-XY-modelquantum1d/7.xy-finiteT/index.md" tabindex="-1"><a href="./quantum1d/7.xy-finiteT/">Finite temperature XY model</a> <a class="header-anchor" href="#Finite-temperature-XY-modelquantum1d/7.xy-finiteT/index.md" aria-label="Permalink to &quot;[Finite temperature XY model](quantum1d/7.xy-finiteT/index.md) {#Finite-temperature-XY-modelquantum1d/7.xy-finiteT/index.md}&quot;">​</a></h3><p><img src="'+s+'" alt=""></p><p>Simulates the finite-temperature XY chain by purifying the infinite-temperature density matrix and evolving it in imaginary time, then compares the resulting partition function and free energy against exact diagonalization and, via BenchmarkFreeFermions.jl, the exact free-fermion solution. A technical, comparison-heavy example built around <code>MPSKit.infinite_temperature_density_matrix</code> and imaginary-time evolution rather than ground-state search. <strong>Level: advanced.</strong></p><h3 id="1D-Bose-Hubbard-modelquantum1d/8.bose-hubbard/index.md" tabindex="-1"><a href="./quantum1d/8.bose-hubbard/">1D Bose-Hubbard model</a> <a class="header-anchor" href="#1D-Bose-Hubbard-modelquantum1d/8.bose-hubbard/index.md" aria-label="Permalink to &quot;[1D Bose-Hubbard model](quantum1d/8.bose-hubbard/index.md) {#1D-Bose-Hubbard-modelquantum1d/8.bose-hubbard/index.md}&quot;">​</a></h3><p><img src="'+m+'" alt=""></p><p>The most comprehensive example in the gallery: works directly in the thermodynamic limit with a truncated bosonic local Hilbert space, extracts correlation functions and the correlation length as a function of bond dimension, computes the momentum distribution, and maps out the Mott-insulator/superfluid structure of the phase diagram from the ground-state response to an applied phase twist. Touches most of the ground-state toolbox (<code>InfiniteMPS</code>, <code>find_groundstate</code>, bond-dimension control, <code>expectation_value</code>-based observables) in a single, longer study. <strong>Level: advanced.</strong></p><h2 id="Classical-20d" tabindex="-1">Classical (2+0)d <a class="header-anchor" href="#Classical-20d" aria-label="Permalink to &quot;Classical (2+0)d {#Classical-20d}&quot;">​</a></h2><h3 id="The-Hard-Hexagon-modelclassic2d/1.hard-hexagon/index.md" tabindex="-1"><a href="./classic2d/1.hard-hexagon/">The Hard Hexagon model</a> <a class="header-anchor" href="#The-Hard-Hexagon-modelclassic2d/1.hard-hexagon/index.md" aria-label="Permalink to &quot;[The Hard Hexagon model](classic2d/1.hard-hexagon/index.md) {#The-Hard-Hexagon-modelclassic2d/1.hard-hexagon/index.md}&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>Extracts the central charge of the hard hexagon lattice gas by finding the leading boundary MPS of its transfer matrix with <code>VUMPS</code> (using Fibonacci-anyon virtual spaces), then fitting the CFT-predicted scaling relation between entanglement entropy and correlation length as the bond dimension is increased. The only classical statistical-mechanics example in the gallery, and the only one demonstrating non-abelian anyonic symmetries (<code>FibonacciAnyon</code>) in MPSKit. <strong>Level: advanced.</strong></p>',35)])])}const C=c(g,[["render",f]]);export{F as __pageData,C as default};
